<script setup>
import { computed, ref } from 'vue';
const props=defineProps({completado:{type:Boolean,default:false}});const emit=defineEmits(['hablar','practicar']);const paso=ref(1),escena=ref(0),clasificacion=ref({}),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set());
const escenas=[{icono:'💼🏠',simple:'I usually work in the office.',continuo:"I'm working from home this week.",senal1:'usually',senal2:'this week'},{icono:'🚌🚗',simple:'She usually takes the bus.',continuo:"Today she's driving.",senal1:'usually',senal2:'today'},{icono:'🌙🚀',simple:'The pipeline runs every night.',continuo:"It's running right now.",senal1:'every night',senal2:'right now'}];const actual=computed(()=>escenas[escena.value]);
const senales=[{t:'every day',tipo:'simple'},{t:'usually',tipo:'simple'},{t:'on Fridays',tipo:'simple'},{t:'right now',tipo:'continuous'},{t:'at the moment',tipo:'continuous'},{t:'this week',tipo:'continuous'}];const clasificadas=computed(()=>Object.keys(clasificacion.value).length);function clasificar(t,tipo){clasificacion.value={...clasificacion.value,[t]:tipo}}
const retos=[{icono:'🚀',frase:"We ___ right now; don't touch the server.",respuesta:'are deploying',opciones:['deploy','deploys','are deploying','deployed'],razon:'Right now señala una acción en curso.'},{icono:'🏠',frase:'He ___ remotely every Friday.',respuesta:'works',opciones:['works','is working','work','working'],razon:'Every Friday indica una rutina.'},{icono:'🧠',frase:'She ___ the answer already.',respuesta:'knows',opciones:['knows','is knowing','know','is know'],razon:'Know es un verbo de estado; normalmente no va en continuo.'},{icono:'❤️',frase:'I ___ to fix this before the demo.',respuesta:'want',opciones:['want','am wanting','wants','wanting'],razon:'Want expresa un estado, no una acción en progreso.'}];const reto=computed(()=>retos[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.respuesta);function responder(o){elegida.value=o;if(correcta.value){const s=new Set(aciertos.value);s.add(retoIdx.value);aciertos.value=s}}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.length;elegida.value=null}
</script>
<template><section class="contrast"><aside class="hero"><small>⚖️ DOS LENTES, UN PRESENTE</small><h2>¿Rutina o escena en vivo?</h2><div><article><span>🔁</span><b>Presente simple</b><p>habitual · permanente · hechos</p></article><i>VS</i><article><span>🔴</span><b>Presente continuo</b><p>ahora · temporal · en progreso</p></article></div></aside><nav><button v-for="n in 3" :key="n" :class="{active:paso===n}" @click="paso=n"><b>0{{n}}</b>{{n===1?'Cambiá la lente':n===2?'Clasificá señales':'Elegí por contexto'}}</button></nav>
<main v-if="paso===1"><header><small>CONTRASTE 1</small><h3>La misma persona, dos momentos</h3><p>La señal de tiempo cambia la lente y también el verbo.</p></header><div class="scene-nav"><button v-for="(x,i) in escenas" :key="i" :class="{active:escena===i}" @click="escena=i">{{x.icono}}</button></div><section class="split"><article><small>🔁 {{actual.senal1}}</small><b>{{actual.simple}}</b><span>Rutina / hecho habitual</span><button @click="emit('hablar',actual.simple,1)">🔊 Escuchar</button></article><div><span>{{actual.icono}}</span><b>CAMBIO DE CONTEXTO</b></div><article><small>🔴 {{actual.senal2}}</small><b>{{actual.continuo}}</b><span>Situación actual / temporal</span><button @click="emit('hablar',actual.continuo,1)">🔊 Escuchar</button></article></section><aside class="state-note"><b>🧠 Ojo con los verbos de estado</b><p><b>know, believe, want, like, need</b> describen estados; casi nunca se usan en continuo: <i>I know</i>, no <s>I am knowing</s>.</p></aside></main>
<main v-else-if="paso===2"><header><small>CONTRASTE 2</small><h3>Clasificador de señales</h3><p>Mandá cada expresión a la lente correcta.</p></header><div class="signals"><button v-for="s in senales" :key="s.t" :class="clasificacion[s.t]===s.tipo?'done':clasificacion[s.t]?'wrong':''" @click="clasificar(s.t,clasificacion[s.t]==='simple'?'continuous':'simple')"><span>{{clasificacion[s.t]==='simple'?'🔁':clasificacion[s.t]==='continuous'?'🔴':'❔'}}</span><b>{{s.t}}</b><small>Tocá para cambiar</small></button></div><div class="bins"><article><b>🔁 SIMPLE</b><span v-for="s in senales.filter(x=>clasificacion[x.t]==='simple')" :key="s.t">{{s.t}}</span></article><article><b>🔴 CONTINUO</b><span v-for="s in senales.filter(x=>clasificacion[x.t]==='continuous')" :key="s.t">{{s.t}}</span></article></div><p class="score">{{clasificadas}}/{{senales.length}} clasificadas · alterná cada ficha hasta que quede verde.</p></main>
<main v-else><header class="challenge-head"><div><small>CONTRASTE 3</small><h3>El contexto manda</h3><p>Buscá la pista antes de elegir el tiempo.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.icono}}</span><button @click="emit('hablar',reto.frase.replace('___',reto.respuesta),1)">{{reto.frase}} 🔊</button><div><button v-for="o in reto.opciones" :key="o" :class="{ok:elegida&&o===reto.respuesta,bad:elegida===o&&o!==reto.respuesta}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ Lente correcta':'↻ Buscá la señal'}}</b> {{reto.razon}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente contexto →</button></article></main><button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>
<style scoped>
.contrast{display:grid;gap:1rem}.hero,main{padding:1rem;border:1px solid #e5c4ae;border-radius:18px;background:#fff}.hero{background:linear-gradient(135deg,#fff4df,#f0f5ff);text-align:center}h2,h3{margin:.15rem 0}.hero>div{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:.7rem;margin-top:.7rem}.hero article{display:grid;padding:.7rem;border-radius:13px;background:#fff}.hero article>span{font-size:1.6rem}.hero i{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;background:#523d69;color:#fff;font-weight:900}small{font-size:.62rem;font-weight:900;letter-spacing:.08em;color:#a45325}nav{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}nav button{display:flex;gap:.5rem;padding:.7rem;border:1px solid var(--color-borde);border-radius:12px;background:#fff}nav button b{color:#b05b2b}nav button.active{border-color:#b05b2b;background:#fff3e8}header p{margin:.3rem 0;color:var(--color-texto-secundario)}.scene-nav{display:flex;justify-content:center;gap:.4rem;margin:.7rem}.scene-nav button{padding:.55rem;border:1px solid var(--color-borde);border-radius:10px;background:#fff;font-size:1.2rem}.scene-nav button.active{border-color:#7855a5;background:#f3edfb}.split{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:.7rem}.split article{display:flex;flex-direction:column;gap:.35rem;padding:1rem;border-radius:15px;background:#fff5e8}.split article:last-child{background:#eef4ff}.split article>b{font:italic 1.1rem Georgia}.split article>span{font-size:.68rem;color:var(--color-texto-tenue)}.split button{border:0;border-radius:8px;background:#523d69;color:#fff;padding:.45rem}.split>div{display:flex;flex-direction:column;align-items:center;font-size:.55rem}.split>div span{font-size:2rem}.state-note{margin-top:.7rem;padding:.7rem;border-left:4px solid #7855a5;border-radius:9px;background:#f4effb}.state-note p{margin:.2rem 0;font-size:.75rem}.signals{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem;margin-top:.8rem}.signals button{display:flex;flex-direction:column;align-items:center;padding:.7rem;border:1px dashed #a999b8;border-radius:11px;background:#faf8fc}.signals button.done{border-style:solid;border-color:var(--color-verde);background:var(--color-verde-suave)}.signals button.wrong{border-style:solid;border-color:#d26b54;background:#fff0ea}.bins{display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin-top:.7rem}.bins article{min-height:80px;padding:.7rem;border-radius:12px;background:#fff3e8}.bins article:last-child{background:#eef4ff}.bins span{display:inline-block;margin:.2rem;padding:.25rem .45rem;border-radius:8px;background:#fff;font-size:.7rem}.score{text-align:center;font-size:.72rem}.challenge-head{display:flex;justify-content:space-between}.challenge-head>b{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#fff0e4;color:#a45325}.challenge{max-width:650px;margin:auto;padding:1rem;border-radius:16px;background:linear-gradient(145deg,#fff3e7,#eef4ff);text-align:center}.challenge>span{font-size:2.6rem}.challenge>button{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.15rem Georgia}.challenge>div{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.challenge>div button{padding:.6rem;border:1px solid var(--color-borde);border-radius:9px;background:#fff}.challenge .ok{border-color:var(--color-verde);background:var(--color-verde-suave)}.challenge .bad{border-color:#d26b54;background:#fff0ea}.next{background:#523d69!important;color:#fff!important;padding:.55rem .8rem!important}.practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:#523d69;color:#fff;font-weight:800}.practice:disabled{background:var(--color-verde)}
@media(max-width:650px){.split{grid-template-columns:1fr}.split>div{transform:rotate(90deg)}.signals{grid-template-columns:1fr 1fr}}@media(max-width:500px){nav,.hero>div,.bins,.challenge>div{grid-template-columns:1fr}.hero i{margin:auto}.signals{grid-template-columns:1fr}}
</style>
